content:
{
 "kind": "sequence",
 "format": 1,
 "id": "seq_cphl_booth_end",
 "name": "Cluster Puck: the booth, the game in review",
 "set": "set_slush_booth",
 "roles": {
  "pbp": {
   "mark": "pbp",
   "label": "Play-by-play"
  },
  "col": {
   "mark": "col",
   "label": "Colour"
  }
 },
 "wall": "feed",
 "wallText": "{venue}",
 "wallSub": "{show}",
 "beats": [
  {
   "id": "b1",
   "shot": {
    "cam": "wide",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "none",
    "cut": "dissolve"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "That's it from {venue}. {away} {awayScore}, {home} {homeScore}.",
     "There's the final horn. {winner} beat {loser}."
    ]
   },
   "gfx": [
    {
     "kind": "score",
     "title": "FINAL",
     "left": "{away}",
     "leftScore": "{awayScore}",
     "right": "{home}",
     "rightScore": "{homeScore}",
     "sub": "{venue}",
     "at": 0.2,
     "for": 0
    },
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE ICE",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ]
  },
  {
   "id": "r1",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "{goalsSaid} tonight. Here's every one of them.",
     "Let's run through the {goalsSaid}."
    ]
   },
   "gfx": [
    {
     "kind": "lower",
     "text": "{col.name}",
     "sub": "Colour",
     "at": 0.4,
     "for": 4.5
    },
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE ICE",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "goalCount",
     "op": ">",
     "value": 0
    }
   ]
  },
  {
   "id": "g_goal",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "{player} for {team}, with {clock} left in the {period}.",
     "{player} scores for {team}. {clock} to go in the {period}.",
     "{player} {strengthSaid}, with {clock} left."
    ]
   },
   "gfx": [
    {
     "kind": "box",
     "source": "feed",
     "title": "REPLAY",
     "side": "right",
     "at": 0,
     "for": 0
    },
    {
     "kind": "lower",
     "text": "{player}",
     "sub": "{team} · {period} {clock}",
     "at": 0.6,
     "for": 0
    }
   ],
   "each": "goals",
   "eachMax": 12,
   "roll": "{reel}"
  },
  {
   "id": "r2",
   "shot": {
    "cam": "wide",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "drift",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "Shots on the night: {shotsAway} for {away}, {shotsHome} for {home}.",
     "{away} put {shotsAway} on net. {home} had {shotsHome}."
    ]
   },
   "gfx": [
    {
     "kind": "table",
     "title": "THE GAME",
     "rows": [
      "Shots: {shotsAway} - {shotsHome}",
      "Penalties: {penaltyCount}",
      "Fights: {fightCount}",
      "Hurt: {injuryCount}"
     ],
     "side": "left",
     "at": 0.3,
     "for": 0
    },
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE ICE",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ]
  },
  {
   "id": "r3",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "col"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "Three stars. {stars.0.name} is the first.",
     "{stars.0.name} gets the first star tonight."
    ]
   },
   "gfx": [
    {
     "kind": "table",
     "title": "THREE STARS",
     "list": "stars",
     "row": "{n}. {name}: {tonight}",
     "limit": 3,
     "side": "right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "stars.0.name",
     "op": "has"
    }
   ]
  },
  {
   "id": "b2",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "It went to a shootout, and {soWinner.name} scored the one that mattered.",
     "Sixty minutes and overtime didn't settle it. {soWinner.name} did, in the shootout."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "endedIn",
     "op": "=",
     "value": "a shootout"
    },
    {
     "fact": "soWinner.name",
     "op": "has"
    }
   ]
  },
  {
   "id": "b3",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "{soScore} in the shootout. Nobody wants to lose a game that way."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "endedIn",
     "op": "=",
     "value": "a shootout"
    },
    {
     "fact": "soScore",
     "op": "has"
    }
   ]
  },
  {
   "id": "b4",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "Overtime, and {decider.name} ended it.",
     "{decider.name} won it in overtime. One shot and they're all going home."
    ]
   },
   "gfx": [
    {
     "kind": "profile",
     "who": "decider",
     "side": "right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "endedIn",
     "op": "=",
     "value": "overtime"
    },
    {
     "fact": "decider.name",
     "op": "has"
    }
   ]
  },
  {
   "id": "b5",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "{decider.name} scored the one that stood up, in {decider.periodSaid}.",
     "The goal that won it was {decider.name}'s, in {decider.periodSaid}. They never trailed after that."
    ]
   },
   "gfx": [
    {
     "kind": "profile",
     "who": "decider",
     "side": "right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "endedIn",
     "op": "=",
     "value": "regulation"
    },
    {
     "fact": "decider.name",
     "op": "has"
    }
   ]
  },
  {
   "id": "b6",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "{winner} were {comebackSaid} at one point. They kept coming.",
     "Remember, {winner} were {comebackSaid}. That's a good win."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "comebackSaid",
     "op": "has"
    }
   ]
  },
  {
   "id": "b7",
   "shot": {
    "cam": "cam3",
    "frame": "close",
    "on": [
     "col"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "And {loser} didn't score at all. That's a shutout."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "shutout",
     "op": "=",
     "value": "true"
    }
   ]
  },
  {
   "id": "b8",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "{fightsSaid} along the way, too."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "fightCount",
     "op": ">",
     "value": 0
    }
   ]
  },
  {
   "id": "b9",
   "shot": {
    "cam": "cam2",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "pull",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "For {col.name}, I'm {pbp.name}. Let's go back to the desk.",
     "That's all from up here. Over to the studio."
    ]
   },
   "gfx": [
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE ICE",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ]
  }
 ]
}
